VALUES (328387, 'tt3531824', NULL, 'Nerve', 'Nerve', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/qmSpHC0CSNyNll9WhlwWYuwoQ28.jpg', 'https://image.tmdb.org/t/p/original/fg04CQyJzuDJ82jm2meY37n9XyE.jpg', 'Industrious high school senior Vee Delmonico has had it with living life on the sidelines. When pressured by friends to join the popular online game Nerve, Vee decides to sign up for just one dare in what seems like harmless fun. But as she finds herself caught up in the thrill of the adrenaline-fueled competition partnered with a mysterious stranger, the game begins to take a sinister turn with increasingly dangerous acts, leading her into a high stakes finale that will determine her entire future.', NULL, NULL, 3.6117, 6.996, 0, 2.25915789473684185e+01, '2026-07-15 12:01:52', '2026-10-17 18:39:57')
