VALUES (40168, 'tt0096046', NULL, 'Scarecrows', 'Scarecrows', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/xaUdO29mwujiz2NcicSAk4u1NIJ.jpg', 'https://image.tmdb.org/t/p/original/ciO8veuklMJFDGjyS8KBaPEyE42.jpg', 'Five men heist the Camp Pendleton payroll and kidnap a pilot and his daughter, who are forced to fly them to Mexico. Enroute a double cross has one of the thieves parachute with the loot into an abandoned farm surrounded by strange scarecrows. The rest of the team jump after their loot and their former partner. Everything happens during the course of one very dark night.', NULL, NULL, 1.628, 5.211, 0, 8.68, '2026-08-31 03:40:48', '2026-10-17 18:39:57')
