VALUES (634904, 'tt7349896', NULL, 'Inherit the Viper', 'Inherit the Viper', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/aaLEThX7CxKJuAQDnrZcecpzu0I.jpg', 'https://image.tmdb.org/t/p/original/7rH1DgNYeQKvyJH20LReTk7yG6m.jpg', 'Since the death of their father, the Riley siblings have kept their heads above water by illegally dealing in painkillers. Josie is managing the business with an iron fist, when her brother, War veteran Kip, is concerned that the risky business is increasingly turning them into outsiders in their small community. While Kip wants to keep his younger brother out of their illegal endeavors, his younger brother is already making plans of his own.', NULL, NULL, 2.9643, 5.3, 0, 6.26, '2026-10-13 02:06:20', '2026-10-17 18:39:57')
